// Turns the OpenAI reply into a LinkedIn Posts API request body.
// LinkedIn "little" text format: reserved characters must be escaped with a
// backslash or the post gets truncated/rejected. Hashtags become
// {hashtag|\#|Tag} templates so they stay clickable.

// >>> Your LinkedIn member URN (from GET https://api.linkedin.com/v2/userinfo -> "sub")
const AUTHOR_URN = 'urn:li:person:EGqD78qR46';

const MAX_CHARS = 2900; // LinkedIn commentary limit is 3000

let raw = (($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '').trim();
raw = raw.replace(/^```[a-z]*\n?|\n?```$/g, '').trim();
if (!raw) {
  throw new Error('OpenAI returned no post text');
}
if (raw.length > MAX_CHARS) {
  const cut = raw.lastIndexOf('\n', MAX_CHARS);
  raw = raw.slice(0, cut > 0 ? cut : MAX_CHARS).trim();
}

const escapeLittle = (s) => s.replace(/[\\|{}@\[\]()<>#*_~]/g, (c) => '\\' + c);

const tags = [];
let text = raw.replace(/#([\p{L}\p{N}_]+)/gu, (m, tag) => {
  tags.push(tag);
  return '\u0000' + (tags.length - 1) + '\u0000';
});
text = escapeLittle(text);
text = text.replace(/\u0000(\d+)\u0000/g, (m, i) => '{hashtag|\\#|' + escapeLittle(tags[Number(i)]) + '}');

return [{
  json: {
    postText: raw,
    body: {
      author: AUTHOR_URN,
      commentary: text,
      visibility: 'PUBLIC',
      distribution: {
        feedDistribution: 'MAIN_FEED',
        targetEntities: [],
        thirdPartyDistributionChannels: []
      },
      lifecycleState: 'PUBLISHED',
      isReshareDisabledByAuthor: false
    }
  }
}];

